defense.secure_config:
# Audit and fix all pre-auth disabled accounts:
Get-ADUser -Filter {DoesNotRequirePreAuth -eq $true} | ForEach-Object {
  Set-ADAccountControl $_ -DoesNotRequirePreAuth $false
  Write-Output "Fixed: $($_.SamAccountName)"
}

# Scheduled task / quarterly audit:
$vuln = Get-ADUser -Filter {DoesNotRequirePreAuth -eq $true}
if ($vuln) { Send-MailMessage -To 'security@corp.local' -Subject 'AS-REP Roastable Accounts Found' -Body ($vuln | Out-String) }

# MDI: 'AS-REP roasting attack' alert enabled by default on MDI deployment
